import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-05-18 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-05-18 :: Ceph Orchestration Meeting","date":"2020-05-18T00:00:00.000Z","updated":"2020-05-19T00:00:00.000Z","tags":["Ceph","分布式存储","CLI重构","代码重构","管理与自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-05-18_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-05-18_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2020/2020-05-18_-_-_Ceph_Orchestration_Meeting.md"};function o(n,l,s,h,u,c){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：2020年5月18日</li><li>时间：具体时间未提供</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Travis</li><li>John</li><li>Lucy</li><li>Tommy</li><li>其他未提及姓名的参与者</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph Y版本发布</strong></p><ul><li>Y版本预计即将发布，可能是当天或本周内。</li></ul></li><li><p><strong>CLI重构讨论</strong></p><ul><li>讨论了如何统一<code>apply</code>和<code>daemon ad</code>命令，特别是在使用Porticus和subversion 3.5或6的情况下。</li><li>提出了CLI重构的建议，包括将讨论转移到会议中，并创建文档记录相关内容。</li><li>讨论了过渡期的挑战，包括旧命令的兼容性和命令冗余性。</li></ul></li><li><p><strong>代码重构和对象导向方法</strong></p><ul><li>讨论了如何通过采用更对象导向的方法来简化代码，特别是在FF Orchestrator中。</li><li>提出了具体的重构步骤，如将特定实现从模块中移出，保持模块独立性。</li></ul></li><li><p><strong>文档更新</strong></p><ul><li>讨论了关于设备文档的更新，建议将相关信息放在设备财务文档中。</li></ul></li><li><p><strong>Drive Group解析和匹配</strong></p><ul><li>讨论了在Ceph中Drive Group解析和匹配的实现，特别是在Rook和Ceph Manager模块中的处理。</li><li>提出了几种匹配机制，如使用主机名、标签等。</li></ul></li><li><p><strong>idempotence of the lv investment</strong></p><ul><li>讨论了lv投资幂等性的实现，提出了一个PR，并请求社区成员进行测试。</li></ul></li><li><p><strong>本地开发和测试环境</strong></p><ul><li>讨论了如何在容器中本地测试和开发，提出了使用本地注册表和容器镜像的方法。</li><li>提出了一些工具和脚本，如cube chicka，以帮助开发和测试。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续讨论CLI重构，并在Google Docs上进行在线评论和讨论。</li><li>继续进行代码重构，特别是在FF Orchestrator中采用更对象导向的方法。</li><li>更新设备文档，并将相关信息放在设备财务文档中。</li><li>继续讨论Drive Group解析和匹配的实现，特别是在Rook和Ceph Manager模块中的处理。</li><li>继续测试和完善lv投资幂等性的实现。</li><li>继续讨论和完善本地开发和测试环境的方法和工具。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>在Google Docs上进行CLI重构的在线评论和讨论。</li><li>继续进行代码重构，特别是在FF Orchestrator中采用更对象导向的方法。</li><li>更新设备文档，并将相关信息放在设备财务文档中。</li><li>继续讨论Drive Group解析和匹配的实现，特别是在Rook和Ceph Manager模块中的处理。</li><li>继续测试和完善lv投资幂等性的实现。</li><li>继续讨论和完善本地开发和测试环境的方法和工具。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到了一些具体的工具和脚本，如cube chicka，以帮助开发和测试。</li><li>会议中提到了一些具体的实现细节，如使用主机名、标签等匹配机制。</li><li>会议中提到了一些具体的代码重构步骤，如将特定实现从模块中移出，保持模块独立性。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，计划下周再次开会。</li></ul>',15)])])}const _=i(r,[["render",o]]);export{d as __pageData,_ as default};
